export function createAudio(onSpeaking,{speech,preferLocal=false,onVoiceLevel=()=>{}}={}){
const $=id=>document.getElementById(id),synth=window.speechSynthesis;let ctx,master,timer,enabled=false,step=0,next=0,active=null,pending=[],watchdog,voices=[],fileAudio=null,fileURL,auraAudio,powered=false;
const status=text=>$('audio-status').textContent=text;
let customReady=false,localReady=false,localSpeech,localPreferred=preferLocal;
function voiceList(){const previous=$('voice-select').value;voices=synth?.getVoices().filter(v=>/^pt/i.test(v.lang))||[];$('voice-select').replaceChildren(new Option('Automática · português do Brasil',''));for(const v of voices)$('voice-select').add(new Option(v.name,v.voiceURI));if(localReady||localPreferred)$('voice-select').add(new Option(localReady?'Voz do amigo · padrão de todas as falas':'Voz do amigo · aguardando preparo','__local'));if(customReady)$('voice-select').add(new Option('Voz personalizada · arquivo autorizado','__custom'));if(previous==='__local'&&(localReady||localPreferred)||previous==='__custom'&&customReady||voices.some(v=>v.voiceURI===previous))$('voice-select').value=previous}
voiceList();if(localPreferred)$('voice-select').value='__local';$('voice-select').onchange=()=>{localPreferred=$('voice-select').value==='__local';clear()};synth?.addEventListener('voiceschanged',voiceList);
let meterFrame,disconnectMeter;const voiceSources=new WeakMap();
function stopMeter(){if(meterFrame)cancelAnimationFrame(meterFrame);meterFrame=null;disconnectMeter?.();disconnectMeter=null;onVoiceLevel(0)}
function trackVoice(clip){
  if(!ctx?.createAnalyser||!ctx?.createMediaElementSource)return;
  const analyser=ctx.createAnalyser();analyser.fftSize=256;const samples=new Uint8Array(analyser.fftSize);
  let source=voiceSources.get(clip);if(!source){source=ctx.createMediaElementSource(clip);voiceSources.set(clip,source)}source.connect(analyser);analyser.connect(ctx.destination);
  disconnectMeter=()=>{source.disconnect();analyser.disconnect()};
  const sample=()=>{analyser.getByteTimeDomainData(samples);let energy=0;for(const value of samples)energy+=((value-128)/128)**2;onVoiceLevel(Math.min(1,Math.max(0,(Math.sqrt(energy/samples.length)-.008)*10)));meterFrame=requestAnimationFrame(sample)};
  sample();
}
function volume(){const gain=enabled&&$('music').checked?Number($('music-volume').value)/100*(active?.2:1):0;if(master&&ctx)master.gain.setTargetAtTime(fileAudio?0:gain,ctx.currentTime,.15);if(fileAudio)fileAudio.volume=gain;if(auraAudio)auraAudio.volume=Number($('aura-volume').value)/100*(active?.35:1)}
function updateAura(){if(enabled&&powered&&$('aura-sound').checked){if(!auraAudio){auraAudio=new Audio('/saiyan-aura.mp3');auraAudio.loop=true;auraAudio.preload='auto';auraAudio.onerror=()=>status('Não foi possível carregar o som da aura.')}volume();if(auraAudio.paused)auraAudio.play().catch(()=>status('Toque em Ativar som para liberar a aura.'))}else if(auraAudio){auraAudio.pause();if(!powered)auraAudio.currentTime=0}}
function tone(midi,time,duration,gain,type='triangle'){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=440*2**((midi-69)/12);g.gain.setValueAtTime(0,time);g.gain.linearRampToValueAtTime(gain,time+.018);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(master);o.start(time);o.stop(time+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
// Original melody, no Dragon Ball composition or recording.
const phrases=[[76,79,83,86,83,79,81,78],[74,78,81,85,81,78,76,74],[72,76,79,84,83,79,76,79],[74,78,81,86,85,81,78,74]];
function schedule(){if(!enabled||!ctx||ctx.state!=='running')return;if(next<ctx.currentTime)next=ctx.currentTime+.03;while(next<ctx.currentTime+.18){const p=Math.floor(step/8)%4,b=step%8;if($('music').checked&&!fileAudio){tone(phrases[p][b],next,.28,.10,'triangle');if(b%2===0){tone([40,38,36,38][p],next,.3,.17);tone(48,next,.055,.16,'sine')}if(b===0){tone([64,62,60,62][p],next,.8,.035,'sawtooth');tone([71,69,67,69][p],next,.8,.03,'sawtooth')}}next+=60/124/2;step++}}
function pump(){if(!enabled||active||!pending.length)return;if(!$('voice').checked){pending=[];return}if($('voice-select').value==='__local'&&!localReady){status('Aguardando preparo da voz do amigo. As falas usarão somente essa voz.');return}const text=pending.shift();if(['__custom','__local'].includes($('voice-select').value)){customSpeech(text,$('voice-select').value==='__local');return}if(!synth)return;const u=new SpeechSynthesisUtterance(text);u.lang='pt-BR';u.rate=1.06;u.pitch=1.02;u.voice=voices.find(v=>v.voiceURI===$('voice-select').value)||voices.find(v=>v.lang==='pt-BR')||null;active=u;onSpeaking(true,text);volume();let done=false;const finish=()=>{if(done||active!==u)return;done=true;clearTimeout(watchdog);active=null;stopMeter();onSpeaking(false);volume();pump()};u.onend=finish;u.onerror=finish;watchdog=setTimeout(()=>{synth.cancel();finish()},Math.max(12000,text.length*150));synth.speak(u)}
async function customSpeech(text,local=false){const controller=new AbortController();let clip,url;const marker={cancel(){controller.abort();clip?.pause();if(url)URL.revokeObjectURL(url)}};active=marker;volume();status(local?'Gerando voz gratuita neste aparelho…':'Gerando fala com a voz personalizada…');const finish=()=>{if(url){URL.revokeObjectURL(url);url=null}if(active!==marker)return;clearTimeout(watchdog);active=null;stopMeter();onSpeaking(false);volume();pump()};try{const blob=await (local?localSpeech:speech)(text,controller.signal);if(active!==marker)return;url=URL.createObjectURL(blob);clip=new Audio(url);clip.onended=()=>{status(local?'Voz gratuita local ativa.':'Voz personalizada ativa.');finish()};clip.onerror=()=>{status('Não foi possível reproduzir a voz personalizada.');finish()};watchdog=setTimeout(()=>{marker.cancel();finish()},60000);clip.onplaying=()=>{if(active===marker){onSpeaking(true,text);stopMeter();try{trackVoice(clip)}catch{stopMeter()}}};clip.onwaiting=()=>{if(active===marker){stopMeter();onSpeaking(false)}};await clip.play()}catch(error){if(active===marker){status('Voz personalizada: '+error.message);finish()}}}

function clear(){pending=[];clearTimeout(watchdog);active?.cancel?.();if(active)synth?.cancel();active=null;stopMeter();onSpeaking(false);volume()}
async function start(){try{if(!ctx){ctx=new(window.AudioContext||window.webkitAudioContext)();master=ctx.createGain();master.connect(ctx.destination)}await ctx.resume();enabled=true;next=ctx.currentTime+.04;clearInterval(timer);timer=setInterval(schedule,80);volume();updateAura();if(fileAudio&&$('music').checked)await fileAudio.play();$('audio-start').textContent='■ Desligar som';status(synth?'Som ativado · voz em português e música.':'Música ativada. Este navegador não oferece síntese de voz.');pump()}catch{status('Não foi possível ativar o áudio. Toque novamente em Ativar som.')}}
function stop(){enabled=false;clear();clearInterval(timer);fileAudio?.pause();updateAura();volume();ctx?.suspend();$('audio-start').textContent='♫ Ativar som e voz';status('Som desligado.')}
$('audio-start').onclick=()=>enabled?stop():start();$('music-volume').oninput=volume;$('aura-volume').oninput=volume;$('aura-sound').onchange=updateAura;$('music').onchange=()=>{volume();if(fileAudio){if(enabled&&$('music').checked)fileAudio.play().catch(()=>status('Toque em Ativar som para iniciar a música.'));else fileAudio.pause()}};$('voice').onchange=()=>{if(!$('voice').checked)clear()};
$('custom-music').onchange=async e=>{const file=e.target.files[0];if(!file)return;fileAudio?.pause();if(fileURL)URL.revokeObjectURL(fileURL);fileURL=URL.createObjectURL(file);fileAudio=new Audio(fileURL);fileAudio.loop=true;fileAudio.onerror=()=>status('Esse arquivo de áudio não pôde ser reproduzido.');volume();if(enabled&&$('music').checked)try{await fileAudio.play()}catch{status('Toque em Ativar som para reproduzir o arquivo.')}};
$('original-music').onclick=()=>{fileAudio?.pause();fileAudio=null;if(fileURL)URL.revokeObjectURL(fileURL);fileURL=null;$('custom-music').value='';volume();status(enabled?'Trilha original ativada.':'Ative o som para ouvir a trilha original.')};
return {setLocalVoice(generator){localSpeech=generator;localReady=Boolean(generator);voiceList();if(localReady){localPreferred=true;$('voice-select').value='__local';pump()}},setPowered(value){powered=Boolean(value);updateAura()},setCustomVoice(ready){const changed=ready&&!customReady;customReady=ready;voiceList();if(changed&&!localReady&&!localPreferred)$('voice-select').value='__custom'},say(text){if(!enabled||!$('voice').checked||!text)return;if(pending.length>=40)pending.shift();pending.push(text);pump()},clear,stop,burst(){if(!enabled||!ctx)return;for(let i=0;i<6;i++)tone(48+i*7,ctx.currentTime+i*.045,.22,.2,'sine')}};
}
